-- Hand-written from lib/db/schema.ts for the LOCAL demo DB (no FKs, lax on purpose).
CREATE TABLE IF NOT EXISTS packages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, service_type text NOT NULL DEFAULT 'Umrah', package_type text NOT NULL DEFAULT 'Reguler', itinerary text NOT NULL DEFAULT '', base_price integer, duration_days integer, status text NOT NULL DEFAULT 'Draft', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), package_id uuid, departure_date date, return_date date, price integer, quota integer, meeting_point text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Terjadwal', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL DEFAULT '', email text, address text NOT NULL DEFAULT '', city text NOT NULL DEFAULT '', customer_type text NOT NULL DEFAULT 'Individu', status text NOT NULL DEFAULT 'Prospek', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_code text NOT NULL, name text NOT NULL, passport_number text NOT NULL DEFAULT '', contact text NOT NULL DEFAULT '', document_status text NOT NULL DEFAULT 'Belum Lengkap', visa_number text NOT NULL DEFAULT '', visa_expiry date, ticket_number text NOT NULL DEFAULT '', room_type text NOT NULL DEFAULT '', jakarta_room_type text NOT NULL DEFAULT '', jakarta_room_no text NOT NULL DEFAULT '', makkah_room_type text NOT NULL DEFAULT '', makkah_room_no text NOT NULL DEFAULT '', madinah_room_type text NOT NULL DEFAULT '', madinah_room_no text NOT NULL DEFAULT '', jamaah_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS manifest_exports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), schedule_id uuid, title text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Draft', generated_by text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS company_identity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, legal_name text NOT NULL DEFAULT '', address text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', email text NOT NULL DEFAULT '', website text NOT NULL DEFAULT '', logo_url text NOT NULL DEFAULT '', document_footer text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS service_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category text NOT NULL DEFAULT 'Wisata', default_duration text NOT NULL DEFAULT '', document_template text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Aktif', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS bank_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bank_name text NOT NULL, account_number text NOT NULL DEFAULT '', account_name text NOT NULL, branch text NOT NULL DEFAULT '', is_primary boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'Aktif', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS booking_statuses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, stage text NOT NULL DEFAULT 'Booking', description text NOT NULL DEFAULT '', payment_impact text NOT NULL DEFAULT '', document_impact text NOT NULL DEFAULT '', owner_role text NOT NULL DEFAULT 'Admin Operasional', mode text NOT NULL DEFAULT 'Aktif', sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_code text NOT NULL, invoice_number text NOT NULL, issue_date date NOT NULL, due_date date NOT NULL, subtotal integer NOT NULL, discount_amount integer NOT NULL DEFAULT 0, total_amount integer NOT NULL, paid_amount integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Draft', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS installments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_code text NOT NULL, invoice_id uuid, sequence integer NOT NULL, label text NOT NULL DEFAULT '', due_date date NOT NULL, amount integer NOT NULL, paid_amount integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'Terjadwal', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_code text NOT NULL, invoice_id uuid, installment_id uuid, bank_account_id uuid, payment_date date NOT NULL, amount integer NOT NULL, method text NOT NULL DEFAULT 'Transfer', reference_number text NOT NULL DEFAULT '', proof_url text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'Tercatat', received_by text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS receipts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL, receipt_number text NOT NULL, issued_date date NOT NULL, received_from text NOT NULL, amount integer NOT NULL, amount_words text NOT NULL DEFAULT '', payment_for text NOT NULL, status text NOT NULL DEFAULT 'Terbit', issued_by text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE company_identity ADD COLUMN IF NOT EXISTS signature_url text NOT NULL DEFAULT ''; ALTER TABLE company_identity ADD COLUMN IF NOT EXISTS signature_name text NOT NULL DEFAULT ''; ALTER TABLE company_identity ADD COLUMN IF NOT EXISTS signature_position text NOT NULL DEFAULT ''; ALTER TABLE company_identity ADD COLUMN IF NOT EXISTS stamp_url text NOT NULL DEFAULT '';
